def parse_args(argv=None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--words", default="assets/data/words.json")
    parser.add_argument("--output", default="assets/data/sentences.json")
    return parser.parse_args(argv)


def main(argv=None) -> None:
    args = parse_args(argv)
    words_path = Path(args.words)
    output_path = Path(args.output)

    if not words_path.exists():
        sys.exit(f"words.json nicht gefunden: {words_path}")

    valid_ids = {w["id"] for w in json.loads(words_path.read_text(encoding="utf-8"))}

    if len(SENTENCE_TRANSLITERATIONS) != len(SENTENCES):
        sys.exit(
            f"SENTENCE_TRANSLITERATIONS ({len(SENTENCE_TRANSLITERATIONS)} "
            f"Eintraege) muss genau so lang sein wie SENTENCES "
            f"({len(SENTENCES)} Eintraege)"
        )

    sentences = []
    per_word: dict[int, int] = {}
    for (word_id, arabic, german, analysis), transliteration in zip(
        SENTENCES, SENTENCE_TRANSLITERATIONS
    ):
        if word_id not in valid_ids:
            sys.exit(f"word_id {word_id} kommt nicht in {words_path} vor")
        arabic = unicodedata.normalize("NFC", arabic)
        if not ARABIC_CHAR_RE.match(arabic):
            sys.exit(f"Ungueltige arabische Zeichen in Satz fuer word_id {word_id}: {arabic!r}")
        if not german.strip():
            sys.exit(f"Leere deutsche Uebersetzung fuer word_id {word_id}")
        if not analysis:
            sys.exit(f"Leere word_analysis fuer word_id {word_id}: {arabic!r}")

        if _mentions_allah(arabic) and FORBIDDEN_ALLAH_TRANSLATION_RE.search(german):
            sys.exit(
                f"'Allah' wird nie uebersetzt (Nutzer-Vorgabe) - Satz fuer "
                f"word_id {word_id} uebersetzt es als 'Gott': {german!r}"
            )
        for w, t in analysis:
            if _mentions_allah(w) and FORBIDDEN_ALLAH_TRANSLATION_RE.search(t):
                sys.exit(
                    f"'Allah' wird nie uebersetzt (Nutzer-Vorgabe) - "
                    f"word_analysis fuer word_id {word_id} uebersetzt es als "
                    f"{t!r}"
                )

        target_index = TARGET_INDEX_OVERRIDES.get((word_id, arabic), 0)
        if target_index >= len(analysis):
            sys.exit(
                f"target_index {target_index} ausserhalb von word_analysis "
                f"fuer word_id {word_id}: {arabic!r}"
            )

        sentences.append(
            {
                "word_id": word_id,
                "arabic": arabic,
                "german": german,
                "transliteration": transliteration,
                "word_analysis": [
                    {"word": unicodedata.normalize("NFC", w), "translation": t}
                    for w, t in analysis
                ],
                "target_index": target_index,
            }
        )
        per_word[word_id] = per_word.get(word_id, 0) + 1

    output_path.parent.mkdir(parents=True, exist_ok=True)
    with output_path.open("w", encoding="utf-8") as f:
        json.dump(sentences, f, ensure_ascii=False, indent=2)
        f.write("\n")

    missing = sorted(valid_ids - set(per_word))
    uneven = sorted(wid for wid, count in per_word.items() if count != 3)

    print(f"Saetze geschrieben: {len(sentences)}")
    print(f"Woerter mit Saetzen: {len(per_word)} / {len(valid_ids)}")
    if missing:
        print(f"Woerter OHNE Satz: {len(missing)} -> {missing}")
    if uneven:
        print(f"Woerter mit != 3 Saetzen: {uneven}")
    print(f"Geschrieben: {output_path}")


if __name__ == "__main__":
    main()
